                if (dp > bit[j]) bit[j] = dp;
            }
            right[i] = Math.max(right[i + 1], dp);
        }

        // Now compute the answer
        int ans = 0;
        for (int p = 1; p <= m; p++) {
            int leftPart = (p > 1) ? left[p - 1] : 0;
            int rightPart = (p < m) ? right[p + 1] : 0;
            int total = leftPart + rightPart + 1;
            if (total > ans) ans = total;
        }

        System.out.println(ans);
    }
