        // Or 1, 2, 2, 1, 2, 2 is not unimodal because it goes up, down, up.
        // 1, 2, 2, 2, 2 is unimodal (non-decreasing: 1,2,2,2,2). Length 5. ✓

        // So we need to find the longest unimodal subsequence of cnt[1..m].

        // A unimodal sequence is one that first non-decreases and then non-increases.
        // We can compute this using dynamic programming.

        // Let left[i] = length of longest non-decreasing subsequence ending at i
        // Let right[i] = length of longest non-increasing subsequence starting at i
        // Then the longest unimodal subsequence with peak at i is left[i] + right[i] - 1

        // But we need the longest subsequence, not necessarily contiguous.
        // Actually, for non-decreasing/non-increasing subsequences, we can use
        // patience sorting or Fenwick tree for O(n log n).

        // Since m <= 100000, O(m log m) is fine.

        // Compute left[i]: longest non-decreasing subsequence ending at i
        // Compute right[i]: longest non-increasing subsequence starting at i

        int[] left = new int[m + 1];
        int[] right = new int[m + 1];

        // For left[i], we want the longest non-decreasing subsequence ending at i.
        // This is similar to LIS but non-decreasing.
        // We can use a Fenwick tree or patience sorting.

        // Let's use patience sorting approach for non-decreasing.
        // Actually, let's use a simpler approach with a Fenwick tree for values.

        // The values cnt[i] are between 0 and n (at most 100000).

        // For left[i]: longest non-decreasing subsequence ending at i.
        // left[i] = 1 + max(left[j]) for j < i and cnt[j] <= cnt[i]

        // For right[i]: longest non-increasing subsequence starting at i.
        // right[i] = 1 + max(right[j]) for j > i and cnt[j] <= cnt[i]

        // We can compute these with Fenwick trees.

        // Fenwick tree for max query.

        int maxVal = n + 1; // cnt values are at most n

        // Compute left
        FenwickTree fenwLeft = new FenwickTree(maxVal + 2);
        for (int i = 1; i <= m; i++) {
            int val = cnt[i];
            if (val == 0) {
                left[i] = 1;
            } else {
                left[i] = fenwLeft.query(val) + 1;
            }
            fenwLeft.update(val, left[i]);
        }

        // Compute right
        FenwickTree fenwRight = new FenwickTree(maxVal + 2);
        for (int i = m; i >= 1; i--) {
            int val = cnt[i];
            if (val == 0) {
                right[i] = 1;
            } else {
                right[i] = fenwRight.query(val) + 1;
            }
            fenwRight.update(val, right[i]);
        }

        int ans = 0;
        for (int i = 1; i <= m; i++) {
            ans = Math.max(ans, left[i] + right[i] - 1);
        }

        System.out.println(ans);
    }

    static class FenwickTree {
        int[] tree;
        int size;

        FenwickTree(int size) {
            this.size = size;
            tree = new int[size + 1];
        }

        void update(int i, int val) {
            while (i <= size) {
                tree[i] = Math.max(tree[i], val);
                i += i & (-i);
            }
        }

        int query(int i) {
            int res = 0;
            while (i > 0) {
                res = Math.max(res, tree[i]);
                i -= i & (-i);
            }
            return res;
        }
    }
}
